def chat_step(config: Dict[str, Any],
              messages: List[Dict[str, Any]],
              tools: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
    """对话工作台用的单步调用：传入完整 messages（含可选 tool 结果），返回助手回合。

    返回 {"role": "assistant", "content": str, "tool_calls": [{"id","name","arguments"}]}。
    tool_calls 为空表示纯文本回复。编排循环（执行工具、回填结果、再调用）在前端完成，
    这里保持无状态。temperature 不被部分模型接受时自动去掉重试。
    """
    client = _client(config)
    model = (config.get("model") or "").strip()
    if not model:
        raise LLMError("未配置模型名，请在设置里填写 model")

    use_temp = True
    last_exc: Optional[Exception] = None
    for _ in range(3):
        kwargs: Dict[str, Any] = {"model": model, "messages": messages}
        if tools:
            kwargs["tools"] = tools
            kwargs["tool_choice"] = "auto"
        if use_temp:
            kwargs["temperature"] = 0
        try:
            resp = client.chat.completions.create(**kwargs)
            msg = resp.choices[0].message
            calls: List[Dict[str, Any]] = []
            for tc in (getattr(msg, "tool_calls", None) or []):
                calls.append({
                    "id": tc.id,
                    "name": tc.function.name,
                    "arguments": tc.function.arguments or "{}",
                })
            return {"role": "assistant", "content": msg.content or "", "tool_calls": calls}
        except Exception as exc:  # noqa: BLE001
            last_exc = exc
            if "temperature" in str(exc).lower() and use_temp:
                use_temp = False
                continue
            break
    raise LLMError(f"模型调用失败：{last_exc}")


