# ---- Agent 对话工作台 ----
def agent_meta(self) -> Dict[str, Any]:
    """返回系统提示与工具 schema，供前端编排循环使用。"""
    return {"ok": True, "system_prompt": orchestrator.SYSTEM_PROMPT, "tools": orchestrator.TOOLS}

def agent_step(self, messages: List[Dict[str, Any]]) -> Dict[str, Any]:
    """单步对话：传入完整 messages，返回助手回合（可能含 tool_calls）。无状态。"""
    cfg = _load_config()
    if not (cfg.get("api_key") or "").strip():
        return {"ok": False, "error": "未配置 API Key，请在「设置」里填写"}
    try:
        msg = llm_client.chat_step(cfg, messages, orchestrator.TOOLS)
        return {"ok": True, "message": msg}
    except llm_client.LLMError as exc:
        return {"ok": False, "error": str(exc)}
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"对话失败：{exc}", "trace": traceback.format_exc()}

