/* ---------- 工具函数 ---------- */
function colToLetter(n) { let s = ""; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }
function letterToCol(s) { let n = 0; for (const ch of s.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64); return n; }
function esc(v) { return String(v == null ? "" : v).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m])); }
function fmtSize(n) { if (!n) return "0 B"; if (n < 1024) return n + " B"; if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB"; return (n / 1024 / 1024).toFixed(1) + " MB"; }
let toastTimer = null;
function toast(msg) { const el = document.getElementById("toast"); el.textContent = msg; el.classList.remove("hidden"); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.add("hidden"), 3500); }

"use strict";

/* ===========================================================================
 * Excel 校对工作台（Agent 对话式）
 * 左：对话流；右：工作区（状态卡 + 焦点区/结果表）。
 * 编排循环放在前端：调 api.agent_step 拿助手回合 → 执行工具 → 回填结果 → 再调。
 * 范围选择这类要用户操作的工具，用 Promise 化的模态实现"挂起/恢复"（await）。
 * =========================================================================== */

const S = {
  baselineDocs: [],
  targetDocs: [],
  relationship: "translation",
  pairing: "row",
  dims: {},
  dimCatalog: [],
  result: null,
  config: {},
  sort: { col: null, dir: 1 },
  filter: { severity: "", dimension: "", file: "" },
  _seq: 1,
};

// 区域选择器临时状态（resolve 用于把"用户选完"回传给 await 它的工具）。
const RM = { docId: null, rangeId: null, grid: null, sel: null, resolve: null };

// Agent 会话：system/tools 来自后端；messages 只存 user/assistant/tool 历史。
const AGENT = { system: "", tools: [], messages: [], busy: false };
const MAX_LOOP = 14; // 单回合内工具调用循环上限，防失控。

function newDoc(file) {
  return {
    id: "d" + (S._seq++),
    path: file ? file.path : null,
    name: file ? file.name : null,
    size: file ? file.size : 0,
    sheets: file && file.sheets ? file.sheets : [],
    missing: file ? !!file.missing : false,
    ranges: [],
  };
}
function newRange(sheet) {
  return { id: "r" + (S._seq++), sheet: sheet || null, range: "", keyCol: null, validated: false, _feedback: null, columns: [] };
}

function api() { return window.pywebview.api; }
function allDocs() { return [...S.baselineDocs, ...S.targetDocs]; }
function findDoc(id) { return allDocs().find((d) => d.id === id); }
function findRange(docId, rid) { const d = findDoc(docId); return d ? d.ranges.find((r) => r.id === rid) : null; }
function groupArr(group) { return group === "baseline" ? S.baselineDocs : S.targetDocs; }

/* 文档引用号：B1/B2 母本，T1/T2 目标。Agent 与状态卡共用。 */
function refOfDoc(d) {
  let i = S.baselineDocs.indexOf(d);
  if (i >= 0) return "B" + (i + 1);
  i = S.targetDocs.indexOf(d);
  if (i >= 0) return "T" + (i + 1);
  return "?";
}
function docByRef(ref) {
  if (!ref) return null;
  const m = /^([BT])(\d+)$/i.exec(String(ref).trim());
  if (!m) return null;
  const arr = m[1].toUpperCase() === "B" ? S.baselineDocs : S.targetDocs;
  return arr[Number(m[2]) - 1] || null;
}

document.addEventListener("DOMContentLoaded", () => {
  if (window.pywebview && window.pywebview.api) init();
  else window.addEventListener("pywebviewready", init, { once: true });
});

async function init() {
  await loadConfig();
  await loadDimensions();
  await initAgent();
  await restoreSession();
  bindChat();
  bindRegionModal();
  bindSettings();
  bindTheme();
  document.getElementById("saveBtn").addEventListener("click", saveSession);
  document.getElementById("resetBtn").addEventListener("click", resetConversation);
  renderState();
  renderFocusEmpty();
  if (!AGENT.messages.length) greet();
}

/* ---------- 配置 / 维度 / Agent 元信息 ---------- */
async function loadConfig() { S.config = await api().get_config(); applyTheme(S.config.theme || "light"); }
async function loadDimensions() {
  const res = await api().dimension_catalog();
  if (res.ok) { S.dimCatalog = res.dimensions; res.dimensions.forEach((d) => { S.dims[d.key] = d.default_on; }); }
}
async function initAgent() {
  const meta = await api().agent_meta();
  if (meta && meta.ok) { AGENT.system = meta.system_prompt; AGENT.tools = meta.tools; }
}

/* ---------- 对话流渲染 ---------- */
function greet() {
  addMsg("assistant", "你好，我是校对助手。告诉我要校对什么，或者直接说\"帮我选母本和目标文档\"，我来一步步配好并跑校对。右侧随时能看到当前配置，也能手动调整。");
}
function bindChat() {
  const form = document.getElementById("chatForm");
  const input = document.getElementById("chatInput");
  form.addEventListener("submit", (e) => { e.preventDefault(); sendMessage(); });
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); }
  });
  input.addEventListener("input", autoGrow);
}
function autoGrow(e) { const t = e.target; t.style.height = "auto"; t.style.height = Math.min(t.scrollHeight, 160) + "px"; }

function addMsg(role, text, kind) {
  const scroll = document.getElementById("chatScroll");
  const wrap = document.createElement("div");
  wrap.className = "msg msg-" + role + (kind ? " msg-" + kind : "");
  if (role === "tool") {
    wrap.innerHTML = `<span class="tool-dot">⚙</span><span class="tool-text">${esc(text)}</span>`;
  } else {
    wrap.innerHTML = `<div class="bubble">${esc(text).replace(/\n/g, "<br>")}</div>`;
  }
  scroll.appendChild(wrap);
  scroll.scrollTop = scroll.scrollHeight;
  return wrap;
}
function addThinking() {
  const scroll = document.getElementById("chatScroll");
  const el = document.createElement("div");
  el.className = "msg msg-assistant thinking";
  el.innerHTML = `<div class="bubble"><span class="typing"><i></i><i></i><i></i></span></div>`;
  scroll.appendChild(el); scroll.scrollTop = scroll.scrollHeight;
  return el;
}

function setBusy(b) {
  AGENT.busy = b;
  document.getElementById("sendBtn").disabled = b;
  document.getElementById("chatInput").disabled = b;
}

async function sendMessage() {
  if (AGENT.busy) return;
  const input = document.getElementById("chatInput");
  const text = input.value.trim();
  if (!text) return;
  if (!S.config.api_key) { toast("未配置 API Key，请先在「设置」中填写"); openSettings(); return; }
  input.value = ""; input.style.height = "auto";
  addMsg("user", text);
  AGENT.messages.push({ role: "user", content: text });
  await runAgentLoop();
}

function stateBlock() {
  const docLine = (d) => {
    const ranges = d.ranges.length
      ? d.ranges.map((r) => `${r.sheet || "?"}!${r.range || "(未设)"}${r.validated ? "✓" : "✗"}${r.keyCol != null ? " key=" + colToLetter(r.keyCol) : ""}`).join("，")
      : "(无范围)";
    return `  ${refOfDoc(d)} ${d.name || "(未选)"}${d.missing ? "[文件缺失]" : ""}｜sheets: ${d.sheets.map((s) => s.name).join("/") || "无"}｜范围: ${ranges}`;
  };
  const dimsOn = S.dimCatalog.filter((d) => S.dims[d.key]).map((d) => d.label).join("、") || "无";
  return [
    "母本文档：" + (S.baselineDocs.length ? "\n" + S.baselineDocs.map(docLine).join("\n") : "（空）"),
    "目标文档：" + (S.targetDocs.length ? "\n" + S.targetDocs.map(docLine).join("\n") : "（空）"),
    `关系：${S.relationship}；配对：${S.pairing}；启用维度：${dimsOn}`,
    `校对结果：${S.result ? (S.result.no_difference ? "已跑，无差异" : "已跑，有 " + (S.result.findings || []).length + " 条") : "尚未运行"}`,
  ].join("\n");
}

function buildMessages() {
  const sys = AGENT.system + "\n\n[当前工作台状态]\n" + stateBlock();
  return [{ role: "system", content: sys }, ...AGENT.messages];
}

async function runAgentLoop() {
  setBusy(true);
  try {
    for (let i = 0; i < MAX_LOOP; i++) {
      const thinking = addThinking();
      let res;
      try { res = await api().agent_step(buildMessages()); }
      finally { thinking.remove(); }
      if (!res || !res.ok) { addMsg("assistant", "出错了：" + ((res && res.error) || "未知错误"), "err"); return; }
      const msg = res.message;
      // 记入历史（assistant 回合，按 OpenAI 格式带 tool_calls）。
      const hist = { role: "assistant", content: msg.content || "" };
      if (msg.tool_calls && msg.tool_calls.length) {
        hist.tool_calls = msg.tool_calls.map((tc) => ({ id: tc.id, type: "function", function: { name: tc.name, arguments: tc.arguments } }));
      }
      AGENT.messages.push(hist);
      if (msg.content) addMsg("assistant", msg.content);
      if (!msg.tool_calls || !msg.tool_calls.length) return; // 纯文本=回合结束

      for (const tc of msg.tool_calls) {
        let args = {};
        try { args = JSON.parse(tc.arguments || "{}"); } catch (_) { args = {}; }
        const result = await execTool(tc.name, args);
        AGENT.messages.push({ role: "tool", tool_call_id: tc.id, content: JSON.stringify(result) });
      }
      // 带着工具结果继续下一轮，让模型决定后续。
    }
    addMsg("assistant", "（已达到本回合的操作上限，先停一下。你可以继续告诉我下一步。）", "err");
  } finally {
    setBusy(false);
    renderState();
  }
}

/* ---------- 工具执行（function calling 的落地） ---------- */
async function execTool(name, args) {
  try {
    switch (name) {
      case "request_documents": return await toolRequestDocuments(args);
      case "use_full_range": return await toolUseFullRange(args);
      case "open_range_selector": return await toolOpenRangeSelector(args);
      case "set_config": return toolSetConfig(args);
      case "run_proofread": return await toolRunProofread();
      case "export_result": return await toolExportResult(args);
      default: return { ok: false, error: "未知工具：" + name };
    }
  } catch (e) {
    return { ok: false, error: String(e) };
  } finally {
    renderState();
  }
}

async function toolRequestDocuments(args) {
  const group = args.group === "target" ? "target" : "baseline";
  const label = group === "baseline" ? "母本" : "目标";
  addMsg("tool", `请选择${label}文档…`);
  const res = await api().pick_file("excel");
  if (res.cancelled) return { ok: false, cancelled: true, note: "用户取消了选择" };
  if (!res.ok) return { ok: false, error: res.error || "选择失败" };
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) return { ok: false, error: sres.error };
  const d = newDoc({ path: res.path, name: res.name, size: res.size, sheets: sres.sheets });
  groupArr(group).push(d);
  addMsg("tool", `已添加${label} ${refOfDoc(d)}：${d.name}（${d.sheets.length} 个 sheet）`);
  return { ok: true, doc_ref: refOfDoc(d), name: d.name, sheets: d.sheets.map((s) => ({ name: s.name, hidden: s.hidden })) };
}

async function toolUseFullRange(args) {
  const d = docByRef(args.doc_ref);
  if (!d) return { ok: false, error: `找不到文档 ${args.doc_ref}` };
  if (!d.sheets.some((s) => s.name === args.sheet)) return { ok: false, error: `${args.doc_ref} 没有 sheet「${args.sheet}」，可选：${d.sheets.map((s) => s.name).join("、")}` };
  const r = newRange(args.sheet);
  d.ranges.push(r);
  await prepareRange(d, r);
  if (!r.validated) { d.ranges = d.ranges.filter((x) => x.id !== r.id); return { ok: false, error: r._feedback && r._feedback.error || "范围无效" }; }
  addMsg("tool", `${refOfDoc(d)} ${args.sheet} 已设为整张已用区域 ${r.range}（${r._feedback.n_rows}×${r._feedback.n_cols}）`);
  return { ok: true, doc_ref: refOfDoc(d), sheet: args.sheet, range: r.range, rows: r._feedback.n_rows, cols: r._feedback.n_cols };
}

async function toolOpenRangeSelector(args) {
  const d = docByRef(args.doc_ref);
  if (!d) return { ok: false, error: `找不到文档 ${args.doc_ref}` };
  if (!d.sheets.some((s) => s.name === args.sheet)) return { ok: false, error: `${args.doc_ref} 没有 sheet「${args.sheet}」` };
  const r = newRange(args.sheet);
  d.ranges.push(r);
  addMsg("tool", `已打开范围选择面板：${refOfDoc(d)} ${args.sheet}，请拖选区域。`);
  const picked = await openRegionFor(d, r);
  if (picked.cancelled) { d.ranges = d.ranges.filter((x) => x.id !== r.id); renderState(); return { ok: false, cancelled: true, note: "用户取消了框选" }; }
  await refreshRange(d, r);
  if (!r.validated) { d.ranges = d.ranges.filter((x) => x.id !== r.id); return { ok: false, error: "所选范围无效" }; }
  addMsg("tool", `${refOfDoc(d)} ${args.sheet} 范围已设为 ${r.range}（${r._feedback.n_rows}×${r._feedback.n_cols}）`);
  return { ok: true, doc_ref: refOfDoc(d), sheet: args.sheet, range: r.range, rows: r._feedback.n_rows, cols: r._feedback.n_cols };
}

function toolSetConfig(args) {
  const changed = [];
  if (args.relationship && ["translation", "same_lang_version", "template_fill"].includes(args.relationship)) { S.relationship = args.relationship; changed.push("关系"); }
  if (args.pairing && ["row", "key"].includes(args.pairing)) { S.pairing = args.pairing; changed.push("配对"); }
  if (Array.isArray(args.dimensions)) {
    const valid = new Set(S.dimCatalog.map((d) => d.key));
    S.dimCatalog.forEach((d) => { if (!d.required) S.dims[d.key] = false; });
    args.dimensions.forEach((k) => { if (valid.has(k)) S.dims[k] = true; });
    S.dimCatalog.forEach((d) => { if (d.required) S.dims[d.key] = true; });
    if (S.relationship === "template_fill") S.dims["sync"] = false;
    changed.push("维度");
  }
  if (changed.length) addMsg("tool", "已更新：" + changed.join("、"));
  const dimsOn = S.dimCatalog.filter((d) => S.dims[d.key]).map((d) => d.key);
  return { ok: true, relationship: S.relationship, pairing: S.pairing, dimensions: dimsOn };
}

async function toolRunProofread() {
  const err = validateReady();
  if (err) return { ok: false, error: err };
  addMsg("tool", "开始校对，请稍候…");
  const res = await runProofreadCore();
  if (!res.ok) return { ok: false, error: res.error };
  const r = res.result;
  if (r.no_difference) return { ok: true, no_difference: true, summary: "未发现差异", notes: r.notes || "" };
  const s = r.summary;
  return { ok: true, no_difference: false, total: (r.findings || []).length, summary: s, notes: r.notes || "" };
}

async function toolExportResult(args) {
  if (!S.result) return { ok: false, error: "还没有可导出的校对结果" };
  const fmt = args.format === "xlsx" ? "xlsx" : "md";
  const res = await api().export_report(fmt, S.result);
  if (res.ok) { addMsg("tool", "已导出：" + res.path); return { ok: true, path: res.path }; }
  return { ok: false, error: res.error || "导出失败" };
}

/* ---------- 右栏：状态卡 ---------- */
function renderState() {
  const host = document.getElementById("workState");
  if (!host) return;
  const docGroup = (group, title) => {
    const arr = groupArr(group);
    const items = arr.length ? arr.map((d) => docCardHtml(d)).join("") : `<div class="st-empty">尚未添加${group === "baseline" ? "母本" : "目标"}</div>`;
    return `<div class="st-group">
      <div class="st-group-h"><h4>${title}</h4><button class="link add-doc" data-group="${group}">+ 添加</button></div>
      ${items}</div>`;
  };
  const relOpts = [["translation", "翻译关系"], ["same_lang_version", "同语言不同版本"], ["template_fill", "模板 vs 填写版"]];
  const pairOpts = [["row", "按行号"], ["key", "按关键列"]];
  host.innerHTML = `
    <div class="st-block">${docGroup("baseline", "母本（标准）")}</div>
    <div class="st-block">${docGroup("target", "目标（校对对象）")}</div>
    <div class="st-block st-config">
      <div class="st-field"><label>关系</label><select id="cfgRel">${relOpts.map(([v, t]) => `<option value="${v}" ${S.relationship === v ? "selected" : ""}>${t}</option>`).join("")}</select></div>
      <div class="st-field"><label>配对</label><select id="cfgPair">${pairOpts.map(([v, t]) => `<option value="${v}" ${S.pairing === v ? "selected" : ""}>${t}</option>`).join("")}</select></div>
      <div class="st-field st-dims"><label>维度</label><div class="dim-chips">${dimChipsHtml()}</div></div>
    </div>
    <button class="btn btn-primary st-run" id="stRun">开始校对</button>`;
  bindStateEvents();
}

function docCardHtml(d) {
  const ref = refOfDoc(d);
  if (d.missing || !d.path) return `<div class="st-doc missing"><div class="st-doc-h"><span class="st-ref">${ref}</span><span class="fname">${esc(d.name || "(未选)")}</span><span class="badge-miss">缺失</span><button class="link del-doc" data-id="${d.id}">删</button></div></div>`;
  const ranges = d.ranges.map((r) => {
    const ok = r.validated && r._feedback && r._feedback.ok;
    const meta = ok ? `${r._feedback.n_rows}×${r._feedback.n_cols}` : (r._feedback && r._feedback.error ? "无效" : "未设");
    const keyHtml = S.pairing === "key" && ok ? `<select class="rg-key" data-doc="${d.id}" data-range="${r.id}"><option value="">关键列…</option>${r.columns.map((c) => `<option value="${c.index}" ${r.keyCol === c.index ? "selected" : ""}>${c.letter}·${esc(c.header) || "空"}</option>`).join("")}</select>` : "";
    return `<div class="st-range ${ok ? "ok" : "warn"}">
      <span class="rg-loc">${esc(r.sheet || "?")}!${esc(r.range || "—")}</span>
      <span class="rg-meta">${meta}</span>${keyHtml}
      <button class="link reselect-range" data-doc="${d.id}" data-range="${r.id}">重选</button>
      <button class="link del-range" data-doc="${d.id}" data-range="${r.id}">×</button>
    </div>`;
  }).join("");
  const sheetOpts = d.sheets.map((s) => `<option value="${esc(s.name)}">${esc(s.name)}${s.hidden ? "(隐藏)" : ""}</option>`).join("");
  return `<div class="st-doc" data-id="${d.id}">
    <div class="st-doc-h"><span class="st-ref">${ref}</span><span class="fname" title="${esc(d.name)}">${esc(d.name)}</span><span class="entry-sub">${d.sheets.length} sheet</span><button class="link del-doc" data-id="${d.id}">删</button></div>
    <div class="st-ranges">${ranges || '<div class="st-norange">未设范围</div>'}</div>
    <div class="st-addrange"><select class="sheet-pick" data-id="${d.id}">${sheetOpts}</select><button class="link add-range" data-id="${d.id}">+ 框选范围</button></div>
  </div>`;
}

function dimChipsHtml() {
  return S.dimCatalog.map((d) => {
    const on = !!S.dims[d.key];
    const locked = d.required;
    const disabled = locked || (d.key === "sync" && S.relationship === "template_fill");
    return `<button class="dim-chip ${on ? "on" : ""} ${disabled ? "locked" : ""}" data-key="${d.key}" ${disabled ? "disabled" : ""} title="${esc(d.desc)}">${d.label}${locked ? "·必选" : ""}</button>`;
  }).join("");
}

function bindStateEvents() {
  const host = document.getElementById("workState");
  host.querySelectorAll(".add-doc").forEach((b) => b.addEventListener("click", () => addDocFile(b.dataset.group)));
  host.querySelectorAll(".del-doc").forEach((b) => b.addEventListener("click", () => { removeDoc(b.dataset.id); }));
  host.querySelectorAll(".del-range").forEach((b) => b.addEventListener("click", () => { const d = findDoc(b.dataset.doc); if (d) { d.ranges = d.ranges.filter((x) => x.id !== b.dataset.range); renderState(); } }));
  host.querySelectorAll(".add-range").forEach((b) => b.addEventListener("click", async () => {
    const d = findDoc(b.dataset.id); if (!d) return;
    const sel = host.querySelector(`.sheet-pick[data-id="${d.id}"]`);
    const sheet = sel ? sel.value : (d.sheets[0] || {}).name;
    if (!sheet) { toast("该文档没有可选 sheet"); return; }
    const r = newRange(sheet); d.ranges.push(r);
    const picked = await openRegionFor(d, r);
    if (picked.cancelled) { d.ranges = d.ranges.filter((x) => x.id !== r.id); renderState(); return; }
    await refreshRange(d, r); renderState();
  }));
  host.querySelectorAll(".reselect-range").forEach((b) => b.addEventListener("click", async () => {
    const d = findDoc(b.dataset.doc); const r = findRange(b.dataset.doc, b.dataset.range);
    if (!d || !r) return;
    const picked = await openRegionFor(d, r);
    if (!picked.cancelled) { await refreshRange(d, r); renderState(); }
  }));
  host.querySelectorAll(".rg-key").forEach((sel) => sel.addEventListener("change", (e) => { const r = findRange(sel.dataset.doc, sel.dataset.range); if (r) r.keyCol = e.target.value ? Number(e.target.value) : null; }));
  const rel = host.querySelector("#cfgRel"); if (rel) rel.addEventListener("change", (e) => { S.relationship = e.target.value; if (S.relationship === "template_fill") S.dims["sync"] = false; renderState(); });
  const pair = host.querySelector("#cfgPair"); if (pair) pair.addEventListener("change", (e) => { S.pairing = e.target.value; renderState(); });
  host.querySelectorAll(".dim-chip").forEach((b) => b.addEventListener("click", () => { if (b.disabled) return; S.dims[b.dataset.key] = !S.dims[b.dataset.key]; renderState(); }));
  const run = host.querySelector("#stRun"); if (run) run.addEventListener("click", manualRun);
}

async function addDocFile(group) {
  const res = await api().pick_file("excel");
  if (res.cancelled) return;
  if (!res.ok) { toast(res.error || "选择失败"); return; }
  const sres = await api().list_sheets(res.path);
  if (!sres.ok) { toast(sres.error); return; }
  groupArr(group).push(newDoc({ path: res.path, name: res.name, size: res.size, sheets: sres.sheets }));
  renderState();
}
function removeDoc(id) {
  S.baselineDocs = S.baselineDocs.filter((d) => d.id !== id);
  S.targetDocs = S.targetDocs.filter((d) => d.id !== id);
  renderState();
}

/* ---------- 范围校验（不依赖步骤式 DOM） ---------- */
async function prepareRange(d, r) {
  const u = await api().used_range(d.path, r.sheet);
  if (u.ok) r.range = u.range;
  await refreshRange(d, r);
}
async function refreshRange(d, r) {
  r.validated = false;
  if (!r.range) { r._feedback = null; r.columns = []; return; }
  const v = await api().validate_range(d.path, r.sheet, r.range);
  r._feedback = v;
  if (v.ok) {
    r.validated = true;
    const cols = await api().detect_columns(d.path, r.sheet, r.range);
    r.columns = cols.ok ? cols.columns : [];
    if (r.keyCol != null && !r.columns.some((c) => c.index === r.keyCol)) r.keyCol = null;
  } else { r.columns = []; }
}

/* ---------- 区域选择器（大模态，Promise 化） ---------- */
function bindRegionModal() {
  document.getElementById("regionCancel").addEventListener("click", () => closeRegion(true));
  document.getElementById("regionModal").addEventListener("click", (e) => { if (e.target.id === "regionModal") closeRegion(true); });
  document.getElementById("regionConfirm").addEventListener("click", confirmRegion);
  document.getElementById("regionAll").addEventListener("click", () => {
    if (!RM.grid) return;
    RM.sel = { r1: 1, r2: RM.grid.rows.length ? RM.grid.rows[RM.grid.rows.length - 1].row : 1, c1: 1, c2: RM.grid.n_cols };
    paintRegion(); syncRegionInput();
  });
  document.getElementById("regionRangeInput").addEventListener("change", (e) => {
    const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(e.target.value.trim());
    if (!m) { toast("范围格式应为 A1:H60"); return; }
    RM.sel = { r1: Math.min(+m[2], +m[4]), r2: Math.max(+m[2], +m[4]), c1: Math.min(letterToCol(m[1]), letterToCol(m[3])), c2: Math.max(letterToCol(m[1]), letterToCol(m[3])) };
    paintRegion(); updateRegionInfo();
  });
}

/* 打开模态并返回 Promise：用户确定→{ok,range}；取消→{cancelled:true}。这就是"挂起/恢复"。 */
function openRegionFor(d, r) {
  return new Promise(async (resolve) => {
    RM.resolve = resolve; RM.docId = d.id; RM.rangeId = r.id; RM.sel = null; RM.grid = null;
    document.getElementById("regionTitle").textContent = `${d.name} · ${r.sheet}`;
    document.getElementById("regionGrid").innerHTML = '<tbody><tr><td style="padding:20px">加载中…</td></tr></tbody>';
    document.getElementById("regionModal").classList.remove("hidden");
    const g = await api().load_grid(d.path, r.sheet);
    if (!g.ok) { toast(g.error || "加载失败"); closeRegion(true); return; }
    RM.grid = g;
    document.getElementById("regionNote").textContent = g.truncated ? `表格较大，仅加载前 ${g.rows.length} 行（其余可手填范围）` : `已用区域 ${g.used_range}`;
    const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(r.range || "");
    RM.sel = m ? { r1: +m[2], r2: +m[4], c1: letterToCol(m[1]), c2: letterToCol(m[3]) } : { r1: 1, r2: g.rows.length, c1: 1, c2: g.n_cols };
    renderRegionGrid(); syncRegionInput();
  });
}
function closeRegion(cancelled) {
  document.getElementById("regionModal").classList.add("hidden");
  if (RM.resolve) { const fn = RM.resolve; RM.resolve = null; fn(cancelled ? { cancelled: true } : { ok: true }); }
}
function confirmRegion() {
  const r = findRange(RM.docId, RM.rangeId);
  if (r && RM.sel) r.range = regionA1();
  document.getElementById("regionModal").classList.add("hidden");
  if (RM.resolve) { const fn = RM.resolve; RM.resolve = null; fn({ ok: true, range: r ? r.range : "" }); }
}

function renderRegionGrid() {
  const g = RM.grid; const tbl = document.getElementById("regionGrid");
  const head = "<thead><tr><th class='corner'>#</th>" + g.col_letters.map((l) => `<th>${l}</th>`).join("") + "</tr></thead>";
  const body = "<tbody>" + g.rows.map((row) =>
    `<tr><th class="rownum">${row.row}</th>` + row.values.map((v, ci) =>
      `<td data-r="${row.row}" data-c="${ci + 1}" title="${esc(v)}">${esc(v)}</td>`).join("") + "</tr>").join("") + "</tbody>";
  tbl.innerHTML = head + body;
  attachRegionDrag(tbl);
  paintRegion();
}
function attachRegionDrag(tbl) {
  let dragging = false, anchor = null;
  const setSel = (a, b) => { RM.sel = { r1: Math.min(a.r, b.r), r2: Math.max(a.r, b.r), c1: Math.min(a.c, b.c), c2: Math.max(a.c, b.c) }; };
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    cell.addEventListener("mousedown", (ev) => { ev.preventDefault(); dragging = true; anchor = { r: +cell.dataset.r, c: +cell.dataset.c }; setSel(anchor, anchor); paintRegion(); updateRegionInfo(); });
    cell.addEventListener("mouseenter", () => { if (dragging && anchor) { setSel(anchor, { r: +cell.dataset.r, c: +cell.dataset.c }); paintRegion(); updateRegionInfo(); } });
  });
  document.addEventListener("mouseup", () => { if (dragging) { dragging = false; syncRegionInput(); } }, { once: true });
}
function paintRegion() {
  const tbl = document.getElementById("regionGrid");
  if (!RM.sel) return;
  const { r1, r2, c1, c2 } = RM.sel;
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    const r = +cell.dataset.r, c = +cell.dataset.c;
    cell.classList.toggle("cell-sel", r >= r1 && r <= r2 && c >= c1 && c <= c2);
  });
  updateRegionInfo();
}
function regionA1() { const s = RM.sel; return s ? `${colToLetter(s.c1)}${s.r1}:${colToLetter(s.c2)}${s.r2}` : ""; }
function updateRegionInfo() {
  const s = RM.sel;
  document.getElementById("regionSelInfo").textContent = s ? `已选 ${regionA1()}（${s.r2 - s.r1 + 1} 行 × ${s.c2 - s.c1 + 1} 列）` : "在表格里拖选单元格";
}
function syncRegionInput() { document.getElementById("regionRangeInput").value = regionA1(); }

/* ---------- 校对核心 ---------- */
function validateReady() {
  if (!S.baselineDocs.length) return "请至少添加一个母本文档";
  if (!S.targetDocs.length) return "请至少添加一个目标文档";
  if (allDocs().some((d) => d.missing)) return "有文件缺失，请重选";
  const bRanges = S.baselineDocs.reduce((n, d) => n + d.ranges.filter((r) => r.validated).length, 0);
  const tRanges = S.targetDocs.reduce((n, d) => n + d.ranges.filter((r) => r.validated).length, 0);
  if (!bRanges) return "母本还没有有效范围";
  if (!tRanges) return "目标还没有有效范围";
  if (allDocs().some((d) => d.ranges.some((r) => r.range && !r.validated))) return "有范围未通过校验";
  if (S.pairing === "key") {
    if (!S.baselineDocs.some((d) => d.ranges.some((r) => r.keyCol != null))) return "按关键列配对：至少一个母本范围要选关键列";
    if (S.targetDocs.some((d) => d.ranges.some((r) => r.validated && r.keyCol == null))) return "按关键列配对：每个目标有效范围都要选关键列";
  }
  return "";
}

function buildPayload() {
  const enabled = Object.keys(S.dims).filter((k) => S.dims[k]);
  const flatten = (docs) => docs.flatMap((d) => d.ranges.filter((r) => r.validated).map((r) => ({ path: d.path, sheet: r.sheet, range: r.range, key_col: r.keyCol })));
  return {
    baselines: flatten(S.baselineDocs),
    targets: flatten(S.targetDocs),
    relationship: S.relationship, pairing_mode: S.pairing, enabled_dimensions: enabled,
    standard: { enabled: false, file_path: null, text: "", note: "", roles: [] },
  };
}

// 进度回调（后端 _emit_progress 调用）
window.__pfProgress = function (done, total, label) {
  const el = document.getElementById("progressText");
  if (el) el.textContent = `已完成 ${done}/${total}：${label}`;
};

async function runProofreadCore() {
  const tgt = S.targetDocs.reduce((n, d) => n + d.ranges.filter((r) => r.validated).length, 0);
  showLoading(tgt);
  try {
    const res = await api().run_proofread(buildPayload());
    if (!res.ok) { showError(res.error || "校对失败"); return { ok: false, error: res.error || "校对失败" }; }
    S.result = res; renderResult();
    return { ok: true, result: res };
  } catch (e) { showError(String(e)); return { ok: false, error: String(e) }; }
}

async function manualRun() {
  if (!S.config.api_key) { toast("未配置 API Key，请先在「设置」中填写"); openSettings(); return; }
  const err = validateReady();
  if (err) { toast(err); return; }
  await runProofreadCore();
}

/* ---------- 右栏焦点区：结果表 ---------- */
function renderFocusEmpty() {
  document.getElementById("workFocus").innerHTML = `<div class="focus-empty"><p>校对结果会显示在这里。</p><p class="hint">在左侧对话里让我帮你配置并跑校对，或用上方状态卡手动操作。</p></div>`;
}
function showLoading(total) {
  document.getElementById("workFocus").innerHTML = `
    <div class="loading"><div class="spin"></div><p>正在校对 ${total} 个目标范围，请稍候…</p>
      <p id="progressText" class="hint"></p>
      <div style="max-width:520px;margin:18px auto 0"><div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:75%"></div><div class="skeleton" style="width:82%"></div></div></div>`;
}
function showError(msg) {
  document.getElementById("workFocus").innerHTML = `<div class="error-box"><p>校对失败：${esc(msg)}</p></div>`;
}
function renderResult() {
  const r = S.result; const host = document.getElementById("workFocus");
  const files = (r.per_target || []).map((t) => t.file);
  if (r.no_difference) {
    host.innerHTML = `<div class="empty"><p>在启用维度下未发现差异。</p>${r.notes ? `<p>${esc(r.notes)}</p>` : ""}
      <p class="hint">已对照 ${r.baselines_count} 个母本范围、${r.targets_count} 个目标范围。</p></div>`;
    return;
  }
  const s = r.summary;
  const fileOpts = files.map((f) => `<option value="${esc(f)}">${esc(f)}</option>`).join("");
  host.innerHTML = `
    <div class="summary-bar">
      <span class="chip high">高 ${s.high}</span><span class="chip mid">中 ${s.medium}</span>
      <span class="chip low">低·可接受 ${s.low_acceptable}</span><span class="chip scope">不在范围 ${s.out_of_scope}</span><span class="chip conf">低置信度 ${s.low_confidence}</span>
    </div>
    ${r.notes ? `<p class="hint">${esc(r.notes)}</p>` : ""}
    <div class="toolbar">
      <label>文件 <select id="fFile"><option value="">全部</option>${fileOpts}</select></label>
      <label>严重度 <select id="fSev"><option value="">全部</option><option>高</option><option>中</option><option>低</option><option>可接受差异</option></select></label>
      <label>维度 <select id="fDim"><option value="">全部</option><option>准确性</option><option>同步</option><option>一致性</option><option>范围</option><option>语气</option></select></label>
      <span class="spacer"></span>
      <button class="btn btn-outline" id="expMd">导出 Markdown</button><button class="btn btn-outline" id="expXlsx">导出 Excel</button>
    </div>
    <div class="result-table-wrap"><table class="result"><thead></thead><tbody></tbody></table></div>`;
  document.getElementById("fFile").addEventListener("change", (e) => { S.filter.file = e.target.value; renderRows(); });
  document.getElementById("fSev").addEventListener("change", (e) => { S.filter.severity = e.target.value; renderRows(); });
  document.getElementById("fDim").addEventListener("change", (e) => { S.filter.dimension = e.target.value; renderRows(); });
  document.getElementById("expMd").addEventListener("click", () => exportReport("md"));
  document.getElementById("expXlsx").addEventListener("click", () => exportReport("xlsx"));
  renderRows();
}

const COLS = ["文件", "位置", "原文", "建议/处理", "维度", "子类型", "严重程度", "置信度", "依据"];
function renderRows() {
  const table = document.querySelector("table.result");
  if (!table) return;
  const thead = table.querySelector("thead");
  thead.innerHTML = "<tr>" + COLS.map((c) => { const arrow = S.sort.col === c ? (S.sort.dir > 0 ? "▲" : "▼") : ""; return `<th data-col="${c}">${c} <span class="arrow">${arrow}</span></th>`; }).join("") + "</tr>";
  thead.querySelectorAll("th").forEach((th) => th.addEventListener("click", () => { const c = th.dataset.col; if (S.sort.col === c) S.sort.dir *= -1; else { S.sort.col = c; S.sort.dir = 1; } renderRows(); }));
  let rows = S.result.findings.slice();
  if (S.filter.file) rows = rows.filter((f) => f["文件"] === S.filter.file);
  if (S.filter.severity) rows = rows.filter((f) => f["严重程度"] === S.filter.severity);
  if (S.filter.dimension) rows = rows.filter((f) => f["维度"] === S.filter.dimension);
  if (S.sort.col) {
    const c = S.sort.col;
    if (c === "严重程度") rows.sort((a, b) => (sevRank(a[c]) - sevRank(b[c])) * S.sort.dir);
    else rows.sort((a, b) => String(a[c]).localeCompare(String(b[c]), "zh") * S.sort.dir);
  }
  const tbody = table.querySelector("tbody");
  tbody.innerHTML = rows.map((f) => `
    <tr><td>${esc(f["文件"])}</td><td class="coord">${esc(f["位置"])}</td><td>${esc(f["原文"])}</td><td>${esc(f["建议/处理"])}</td>
    <td>${esc(f["维度"])}</td><td>${esc(f["子类型"])}</td><td>${sevBadge(f["严重程度"])}</td><td>${esc(f["置信度"])}</td>
    <td class="evidence" title="${esc(f["依据"])}">${esc(f["依据"])}</td></tr>`).join("");
  if (!rows.length) tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--text-muted);padding:24px">当前筛选无结果</td></tr>`;
}
function sevRank(s) { return { "高": 0, "中": 1, "低": 2, "可接受差异": 3 }[s] ?? 9; }
function sevBadge(s) { const cls = { "高": "s-high", "中": "s-mid", "低": "s-low", "可接受差异": "s-acc" }[s] || "s-acc"; return `<span class="sev ${cls}"><span class="dot"></span>${esc(s)}</span>`; }
async function exportReport(fmt) { const res = await api().export_report(fmt, S.result); toast(res.ok ? "已导出：" + res.path : (res.error || "导出失败")); }

/* ---------- 会话保存 / 恢复 ---------- */
function collectSession() {
  const slim = (d) => ({ path: d.path, name: d.name, ranges: d.ranges.map((r) => ({ sheet: r.sheet, range: r.range, keyCol: r.keyCol })) });
  return {
    baselineDocs: S.baselineDocs.map(slim),
    targetDocs: S.targetDocs.map(slim),
    relationship: S.relationship, pairing: S.pairing, dims: S.dims,
  };
}
async function saveSession() {
  const res = await api().save_session(collectSession());
  toast(res.ok ? "配置已保存，下次启动自动恢复" : (res.error || "保存失败"));
}
async function restoreSession() {
  const res = await api().load_session();
  if (!res.ok || !res.session) return;
  const ss = res.session;
  const rebuild = async (arr) => {
    const out = [];
    for (const it of arr || []) {
      const d = newDoc({ path: it.path, name: it.name, size: 0, sheets: [], missing: it.missing });
      if (!it.missing && it.path) { const sres = await api().list_sheets(it.path); if (sres.ok) d.sheets = sres.sheets; }
      for (const rr of (it.ranges || [])) {
        const ri = newRange(rr.sheet); ri.range = rr.range || ""; ri.keyCol = rr.keyCol ?? null;
        d.ranges.push(ri);
        if (!d.missing && ri.range) await refreshRange(d, ri);
      }
      out.push(d);
    }
    return out;
  };
  S.baselineDocs = await rebuild(ss.baselineDocs);
  S.targetDocs = await rebuild(ss.targetDocs);
  if (ss.relationship) S.relationship = ss.relationship;
  if (ss.pairing) S.pairing = ss.pairing;
  if (ss.dims) S.dims = ss.dims;
  const miss = allDocs().filter((d) => d.missing).length;
  if (miss) toast(`已恢复上次配置，有 ${miss} 个文件找不到，请重选`);
}

function resetConversation() {
  AGENT.messages = [];
  document.getElementById("chatScroll").innerHTML = "";
  greet();
}

/* ---------- 设置 ---------- */
function bindSettings() {
  document.getElementById("settingsBtn").addEventListener("click", openSettings);
  document.getElementById("cfgCancel").addEventListener("click", closeModal);
  document.getElementById("cfgSave").addEventListener("click", saveSettings);
  document.getElementById("settingsModal").addEventListener("click", (e) => { if (e.target.id === "settingsModal") closeModal(); });
}
function openSettings() {
  document.getElementById("cfgBaseUrl").value = S.config.base_url || "";
  document.getElementById("cfgModel").value = S.config.model || "";
  document.getElementById("cfgKey").value = S.config.api_key || "";
  document.getElementById("cfgTimeout").value = S.config.request_timeout || 120;
  document.getElementById("settingsModal").classList.remove("hidden");
}
function closeModal() { document.getElementById("settingsModal").classList.add("hidden"); }
async function saveSettings() {
  S.config.base_url = document.getElementById("cfgBaseUrl").value.trim();
  S.config.model = document.getElementById("cfgModel").value.trim();
  S.config.api_key = document.getElementById("cfgKey").value.trim();
  S.config.request_timeout = Number(document.getElementById("cfgTimeout").value) || 120;
  const res = await api().save_config(S.config);
  if (res.ok) { toast("设置已保存"); closeModal(); } else toast(res.error || "保存失败");
}

/* ---------- 主题 ---------- */
function bindTheme() {
  document.getElementById("themeBtn").addEventListener("click", async () => {
    const next = (S.config.theme === "dark") ? "light" : "dark";
    applyTheme(next); S.config.theme = next; await api().save_config(S.config);
  });
}
function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  document.getElementById("themeIcon").textContent = theme === "dark" ? "🌙" : "🌞";
  S.config.theme = theme;
}

/* ---------- 工具函数 ---------- */
function colToLetter(n) { let s = ""; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; }
function letterToCol(s) { let n = 0; for (const ch of s.toUpperCase()) n = n * 26 + (ch.charCodeAt(0) - 64); return n; }
function esc(v) { return String(v == null ? "" : v).replace(/[&<>"']/g, (m) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[m])); }
function fmtSize(n) { if (!n) return "0 B"; if (n < 1024) return n + " B"; if (n < 1024 * 1024) return (n / 1024).toFixed(1) + " KB"; return (n / 1024 / 1024).toFixed(1) + " MB"; }
let toastTimer = null;
function toast(msg) { const el = document.getElementById("toast"); el.textContent = msg; el.classList.remove("hidden"); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.add("hidden"), 3500); }

