/* 布局 */
.layout { display: flex; height: calc(100vh - 49px); }
.stepper {
  width: 240px; flex-shrink: 0;
  background: var(--surface); border-right: 1px solid var(--border);
  padding: 16px 12px; display: flex; flex-direction: column; gap: 6px;
}
.step {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 12px; border: none; border-radius: var(--radius);
  background: transparent; color: var(--text-muted);
  cursor: pointer; text-align: left; font: inherit; width: 100%;
  transition: background .15s ease;
}
.step:hover { background: var(--surface-2); }
.step.active { background: var(--primary-soft); color: var(--text); }
.step-no {
  width: 26px; height: 26px; flex-shrink: 0; border-radius: 50%;
  display: grid; place-items: center; font-weight: 700;
  background: var(--surface-2); color: var(--text-muted);
}
.step.active .step-no { background: var(--primary); color: var(--primary-contrast); }
.step.done .step-no { background: var(--success); color: #fff; }
.step-text { display: flex; flex-direction: column; }
.step-text small { color: var(--text-muted); font-size: 11px; }

.content { flex: 1; overflow-y: auto; padding: 24px 30px 90px; }
