.chat-scroll { flex: 1; overflow-y: auto; padding: 20px 22px; display: flex; flex-direction: column; gap: 14px; }
.chat-input-bar { display: flex; gap: 10px; align-items: flex-end; padding: 12px 16px; border-top: 1px solid var(--border); background: var(--surface); }
.chat-input-bar textarea { flex: 1; resize: none; max-height: 160px; line-height: 1.5; }
.chat-input-bar .btn { flex-shrink: 0; }

/* 对话气泡 */
.msg { display: flex; }
