    if (!RM.grid) return;
    RM.sel = { r1: 1, r2: RM.grid.rows.length ? RM.grid.rows[RM.grid.rows.length - 1].row : 1, c1: 1, c2: RM.grid.n_cols };
    paintRegion(); syncRegionInput();
  });
