    RM.wrap = !RM.wrap;
    const tbl = document.getElementById("regionGrid");
    if (tbl) tbl.classList.toggle("wrap", RM.wrap);
    e.currentTarget.setAttribute("aria-pressed", String(RM.wrap));
    e.currentTarget.classList.toggle("active", RM.wrap);
  });
  document.getElementById("regionRangeInput").addEventListener("change", (e) => {
    const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(e.target.value.trim());
    if (!m) { toast("范围格式应为 A1:H60"); return; }
    RM.sel = { r1: Math.min(+m[2], +m[4]), r2: Math.max(+m[2], +m[4]), c1: Math.min(letterToCol(m[1]), letterToCol(m[3])), c2: Math.max(letterToCol(m[1]), letterToCol(m[3])) };
    paintRegion(); updateRegionInfo();
  });
}

/* 打开模态并返回 Promise：用户确定→{ok,range}；取消→{cancelled:true}。这就是"挂起/恢复"。 */
function openRegionFor(d, r) {
  return new Promise(async (resolve) => {
    RM.resolve = resolve; RM.docId = d.id; RM.rangeId = r.id; RM.sel = null; RM.grid = null; RM.rowH = {};
    document.getElementById("regionTitle").textContent = `${d.name} · ${r.sheet}`;
    document.getElementById("regionGrid").innerHTML = '<tbody><tr><td style="padding:20px">加载中…</td></tr></tbody>';
    document.getElementById("regionModal").classList.remove("hidden");
    const g = await api().load_grid(d.path, r.sheet);
    if (!g.ok) { toast(g.error || "加载失败"); closeRegion(true); return; }
    RM.grid = g;
    RM.colW = g.col_letters.map(() => DEFAULT_COL_W);
    document.getElementById("regionNote").textContent = g.truncated ? `表格较大，仅加载前 ${g.rows.length} 行（其余可手填范围）` : `已用区域 ${g.used_range}`;
    const m = /^([A-Za-z]+)(\d+):([A-Za-z]+)(\d+)$/.exec(r.range || "");
    RM.sel = m ? { r1: +m[2], r2: +m[4], c1: letterToCol(m[1]), c2: letterToCol(m[3]) } : { r1: 1, r2: g.rows.length, c1: 1, c2: g.n_cols };
    renderRegionGrid(); syncRegionInput();
  });
}
function closeRegion(cancelled) {
  document.getElementById("regionModal").classList.add("hidden");
  if (RM.resolve) { const fn = RM.resolve; RM.resolve = null; fn(cancelled ? { cancelled: true } : { ok: true }); }
}
function confirmRegion() {
  const r = findRange(RM.docId, RM.rangeId);
  if (r && RM.sel) r.range = regionA1();
  document.getElementById("regionModal").classList.add("hidden");
  if (RM.resolve) { const fn = RM.resolve; RM.resolve = null; fn({ ok: true, range: r ? r.range : "" }); }
}

function renderRegionGrid() {
  const g = RM.grid; const tbl = document.getElementById("regionGrid");
  tbl.classList.toggle("wrap", RM.wrap);
  const colgroup = `<colgroup><col class="cg-corner" />` +
    g.col_letters.map((l, i) => `<col style="width:${RM.colW[i]}px" />`).join("") + `</colgroup>`;
  const head = `<thead><tr><th class="corner">#</th>` +
    g.col_letters.map((l, i) =>
      `<th class="colh" data-c="${i + 1}"><span class="colh-label">${esc(l)}</span><span class="col-resize" data-c="${i + 1}" title="拖动改列宽，双击自适应"></span></th>`).join("") +
    `</tr></thead>`;
  const body = "<tbody>" + g.rows.map((row) => {
    const hStyle = RM.rowH[row.row] ? ` style="height:${RM.rowH[row.row]}px"` : "";
    return `<tr${hStyle}><th class="rownum" data-r="${row.row}"><span class="rownum-label">${row.row}</span><span class="row-resize" data-r="${row.row}" title="拖动改行高"></span></th>` +
      row.values.map((v, ci) => `<td data-r="${row.row}" data-c="${ci + 1}" title="${esc(v)}">${esc(v)}</td>`).join("") + "</tr>";
  }).join("") + "</tbody>";
  tbl.innerHTML = colgroup + head + body;
  attachRegionEvents(tbl);
  paintRegion();
}

function attachRegionEvents(tbl) {
  let dragging = false, anchor = null;
  const setSel = (a, b) => { RM.sel = { r1: Math.min(a.r, b.r), r2: Math.max(a.r, b.r), c1: Math.min(a.c, b.c), c2: Math.max(a.c, b.c) }; };

  // 单元格拖选
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    cell.addEventListener("mousedown", (ev) => { ev.preventDefault(); dragging = true; anchor = { r: +cell.dataset.r, c: +cell.dataset.c }; setSel(anchor, anchor); paintRegion(); updateRegionInfo(); showCellFull(cell); });
    cell.addEventListener("mouseenter", () => { if (dragging && anchor) { setSel(anchor, { r: +cell.dataset.r, c: +cell.dataset.c }); paintRegion(); updateRegionInfo(); } else { showCellFull(cell); } });
  });
  document.addEventListener("mouseup", () => { if (dragging) { dragging = false; syncRegionInput(); } }, { once: true });

  // 列宽手柄：拖动改宽，双击自适应
  tbl.querySelectorAll(".col-resize").forEach((h) => {
    h.addEventListener("mousedown", (ev) => startColResize(ev, +h.dataset.c, tbl));
    h.addEventListener("dblclick", (ev) => { ev.stopPropagation(); autoFitCol(+h.dataset.c, tbl); });
    h.addEventListener("click", (ev) => ev.stopPropagation());
  });
  // 行高手柄
  tbl.querySelectorAll(".row-resize").forEach((h) => {
    h.addEventListener("mousedown", (ev) => startRowResize(ev, +h.dataset.r, h));
    h.addEventListener("click", (ev) => ev.stopPropagation());
  });
  // 点列头选整列、点行号选整行（避开手柄）
  tbl.querySelectorAll("th.colh").forEach((th) => th.addEventListener("click", (ev) => {
    if (ev.target.classList.contains("col-resize")) return;
    const c = +th.dataset.c, last = RM.grid.rows.length ? RM.grid.rows[RM.grid.rows.length - 1].row : 1;
    RM.sel = { r1: 1, r2: last, c1: c, c2: c }; paintRegion(); syncRegionInput();
  }));
  tbl.querySelectorAll("th.rownum").forEach((th) => th.addEventListener("click", (ev) => {
    if (ev.target.classList.contains("row-resize")) return;
    const r = +th.dataset.r; RM.sel = { r1: r, r2: r, c1: 1, c2: RM.grid.n_cols }; paintRegion(); syncRegionInput();
  }));
}

function startColResize(ev, c, tbl) {
  ev.preventDefault(); ev.stopPropagation();
  const colEl = tbl.querySelectorAll("colgroup col")[c]; // index 0 是 corner，故第 c 个对应该列
  const startX = ev.clientX, startW = RM.colW[c - 1] || DEFAULT_COL_W;
  const onMove = (e) => { const w = Math.max(36, startW + (e.clientX - startX)); RM.colW[c - 1] = w; if (colEl) colEl.style.width = w + "px"; };
  const onUp = () => { document.removeEventListener("mousemove", onMove); document.removeEventListener("mouseup", onUp); };
  document.addEventListener("mousemove", onMove); document.addEventListener("mouseup", onUp);
}
function startRowResize(ev, r, handle) {
  ev.preventDefault(); ev.stopPropagation();
  const tr = handle.closest("tr");
  const startY = ev.clientY, startH = tr ? tr.offsetHeight : 24;
  const onMove = (e) => { const h = Math.max(20, startH + (e.clientY - startY)); RM.rowH[r] = h; if (tr) tr.style.height = h + "px"; };
  const onUp = () => { document.removeEventListener("mousemove", onMove); document.removeEventListener("mouseup", onUp); };
  document.addEventListener("mousemove", onMove); document.addEventListener("mouseup", onUp);
}
function autoFitCol(c, tbl) {
  let maxLen = (RM.grid.col_letters[c - 1] || "").length;
  RM.grid.rows.forEach((row) => { const v = row.values[c - 1] || ""; if (v.length > maxLen) maxLen = v.length; });
  const w = Math.max(40, Math.min(460, maxLen * 8 + 20));
  RM.colW[c - 1] = w;
  const colEl = tbl.querySelectorAll("colgroup col")[c];
  if (colEl) colEl.style.width = w + "px";
}
function showCellFull(cell) {
  const bar = document.getElementById("regionCellbar");
  if (!bar) return;
  const v = cell.getAttribute("title") || "";
  const coord = colToLetter(+cell.dataset.c) + cell.dataset.r;
  bar.textContent = v ? `${coord}：${v}` : `${coord}：(空)`;
}

function paintRegion() {
  const tbl = document.getElementById("regionGrid");
  if (!RM.sel || !tbl) return;
  const { r1, r2, c1, c2 } = RM.sel;
  tbl.querySelectorAll("td[data-r]").forEach((cell) => {
    const r = +cell.dataset.r, c = +cell.dataset.c;
    cell.classList.toggle("cell-sel", r >= r1 && r <= r2 && c >= c1 && c <= c2);
  });
  tbl.querySelectorAll("th.colh").forEach((th) => { const c = +th.dataset.c; th.classList.toggle("hl", c >= c1 && c <= c2); });
  tbl.querySelectorAll("th.rownum").forEach((th) => { const r = +th.dataset.r; th.classList.toggle("hl", r >= r1 && r <= r2); });
  updateRegionInfo();
}
function regionA1() { const s = RM.sel; return s ? `${colToLetter(s.c1)}${s.r1}:${colToLetter(s.c2)}${s.r2}` : ""; }
function updateRegionInfo() {
  const s = RM.sel;
  document.getElementById("regionSelInfo").textContent = s ? `已选 ${regionA1()}（${s.r2 - s.r1 + 1} 行 × ${s.c2 - s.c1 + 1} 列）` : "在表格里拖选单元格";
}
function syncRegionInput() { document.getElementById("regionRangeInput").value = regionA1(); }

