/* ---------- 右侧工作区面板：开合 + 拖宽 ---------- */
function bindPanel() {
  document.getElementById("panelToggle").addEventListener("click", () => setPanel(!WP.open));
  const rz = document.getElementById("workResizer");
  rz.addEventListener("mousedown", (e) => {
    e.preventDefault();
    const startX = e.clientX, startW = WP.width;
    const onMove = (ev) => { WP.width = Math.min(900, Math.max(300, startW - (ev.clientX - startX))); applyPanelWidth(); };
    const onUp = () => { document.removeEventListener("mousemove", onMove); document.removeEventListener("mouseup", onUp); };
    document.addEventListener("mousemove", onMove); document.addEventListener("mouseup", onUp);
  });
}
function setPanel(open) {
  WP.open = open;
  document.querySelector(".workbench").classList.toggle("panel-open", open);
  const btn = document.getElementById("panelToggle");
  btn.classList.toggle("active", open); btn.setAttribute("aria-pressed", String(open));
  applyPanelWidth();
}
function applyPanelWidth() {
  const wp = document.querySelector(".work-pane");
  if (wp) wp.style.width = WP.open ? WP.width + "px" : "";
}
function openPanel() { if (!WP.open) setPanel(true); }

