def _materials_block(materials: Optional[List[Dict[str, Any]]]) -> str:
    if not materials:
        return "本轮未提供补充材料。术语/格式/语气类问题只能作为“一致性建议”，不得把你自己的译法当官方标准。"
    evidence = [m for m in materials if m.get("kind") == "evidence"]
    context = [m for m in materials if m.get("kind") == "context"]
    lines: List[str] = []
    if evidence:
        lines.append("【判据材料】可在被授权角色内当权威依据：")
        for m in evidence:
            roles = "、".join(m.get("roles", [])) or "（未指定角色）"
            lines.append(f"- {m.get('name', '')}（授权角色：{roles}；权威：{m.get('authority', '中')}）：{m.get('summary', '')}")
        lines.append("判据使用边界：")
        lines.append("- 含“术语”：术语统一类可引为权威，置信度可给“高”，“依据”引该材料片段。")
        lines.append("- 含“格式”：日期/单位/标点/大小写按其判。")
        lines.append("- 含“语气”：风格/强度可按其判，否则仅作建议。")
        lines.append("- 含“法务”：法务措辞以其为准。")
        lines.append("- 未被授权的角色，判据不参与判断；判据与母本冲突时标“基准冲突”，不要擅自二选一。")
    if context:
        lines.append("【背景材料】仅帮助你理解语境，绝不可单独作为判错依据：")
        for m in context:
            lines.append(f"- {m.get('name', '')}：{m.get('summary', '')}")
        lines.append("背景材料只用于读懂上下文/消歧；据此不得直接判定目标为错，最多在“依据”里说明语境。")
    return "\n".join(lines)

