input.new_string:
def _render_materials(materials: Optional[List[Dict[str, Any]]]) -> str:
    if not materials:
        return "（本轮未提供补充材料）"
    blocks: List[str] = []
    for m in materials:
        is_ev = m.get("kind") == "evidence"
        head = f"[{'判据' if is_ev else '背景'}] {m.get('name', '')}"
        meta: List[str] = []
        if is_ev:
            meta.append("授权角色：" + ("、".join(m.get("roles", [])) or "未指定"))
            meta.append("权威：" + m.get("authority", "中"))
        if m.get("summary"):
            meta.append("说明：" + m["summary"])
        block = head + (("\n  " + "；".join(meta)) if meta else "") + "\n  内容：\n" + (m.get("text", "") or "")
        blocks.append(block)
    return "\n\n".join(blocks)

def pick_material_file(self) -> Dict[str, Any]:
    """补充材料：弹文件对话框，抽取纯文本并返回预览（供 Agent 归纳）。"""
    window = self._window()
    if window is None:
        return {"ok": False, "error": "窗口未就绪"}
    file_types = ("参考文件 (*.xlsx;*.xlsm;*.docx;*.md;*.txt)", "所有文件 (*.*)")
    try:
        result = window.create_file_dialog(
            webview.FileDialog.OPEN, allow_multiple=False, file_types=file_types
        )
    except Exception as exc:  # noqa: BLE001
        return {"ok": False, "error": f"打开文件对话框失败：{exc}"}
    if not result:
        return {"ok": False, "cancelled": True}
    path = result[0]
    try:
        text = standard.extract_text_from_file(path)
    except standard.StandardError as exc:
        return {"ok": False, "error": str(exc)}
    return {
        "ok": True,
        "path": path,
        "name": os.path.basename(path),
        "preview": text[:1500],
        "length": len(text),
    }

