const MAT_ROLES = ["术语", "格式", "语气", "法务"];
async function toolAttachMaterial() {
  addMsg("tool", "请选择参考文档…");
  const res = await api().pick_material_file();
  if (res.cancelled) return { ok: false, cancelled: true, note: "用户取消了选择" };
  if (!res.ok) return { ok: false, error: res.error || "读取失败" };
  addMsg("tool", `已读取参考文档：${res.name}（${res.length} 字），请归纳后用 save_material 存入`);
  return { ok: true, name: res.name, path: res.path, preview: res.preview, length: res.length };
}
function toolSaveMaterial(args) {
  const kind = args.kind === "evidence" ? "evidence" : "context";
  const source = args.source === "text" ? "text" : "file";
  if (source === "file" && !args.path) return { ok: false, error: "source=file 需提供 path（先调 attach_material）" };
  if (source === "text" && !String(args.text || "").trim()) return { ok: false, error: "source=text 需提供 text" };
  const mat = {
    id: "m" + (S._seq++),
    name: (args.name || (source === "file" ? "参考文档" : "补充说明")).trim(),
    kind,
    summary: (args.summary || "").trim(),
    authority: ["高", "中", "参考"].includes(args.authority) ? args.authority : (kind === "context" ? "参考" : "中"),
    roles: kind === "evidence" ? (args.roles || []).filter((r) => MAT_ROLES.includes(r)) : [],
    source,
    path: source === "file" ? args.path : null,
    text: source === "text" ? args.text : null,
  };
  S.materials.push(mat);
  addMsg("tool", `已加入${kind === "evidence" ? "判据" : "背景"}材料：${mat.name}`);
  return { ok: true, material: { name: mat.name, kind: mat.kind, roles: mat.roles, authority: mat.authority } };
}

